<template>
  <q-page class="setup-page">
    <main class="setup-shell">
      <header class="setup-header">
        <button type="button" class="close-button" aria-label="Cancel accommodation setup" @click="handleClose">
          <IconifyIcon icon="lucide:x" width="20" aria-hidden="true" />
        </button>
        <div><h1>New accommodation</h1><p>{{ stepTitle }} · Step {{ currentStep }} of {{ steps.length }}</p></div>
      </header>

      <nav class="stepper" aria-label="Accommodation setup progress">
        <button v-for="step in steps" :key="step.value" type="button" :class="{ active: currentStep === step.value, complete: currentStep > step.value }" :aria-current="currentStep === step.value ? 'step' : undefined" @click="goToStep(step.value)">
          <span>{{ step.value }}</span><small>{{ step.label }}</small>
        </button>
      </nav>

      <section class="setup-content">
        <div v-if="currentStep === 1" class="step-content">
          <div class="step-copy"><h2>About the accommodation</h2><p>Describe the building. Room details are added later, one room at a time.</p></div>
          <label>Accommodation name <span>*</span><q-input v-model="form.name" outlined placeholder="e.g. Sunrise Student Residence" :error="!!stepError.name" :error-message="stepError.name" /></label>
          <label>Accommodation type <span>*</span><q-select v-model="form.accommodationType" :options="accommodationTypes" outlined emit-value map-options :error="!!stepError.accommodationType" :error-message="stepError.accommodationType" /></label>
          <label v-if="form.accommodationType === 'other'">Describe the accommodation type <span>*</span><q-input v-model="form.customAccommodationType" outlined placeholder="e.g. Mixed-use residence" /></label>
          <fieldset><legend>Who can stay <span>*</span></legend><div class="choice-grid"><button v-for="option in genderOptions" :key="option.value" type="button" :class="{ active: form.genderPolicy === option.value }" :aria-pressed="form.genderPolicy === option.value" @click="form.genderPolicy = option.value">{{ option.label }}</button></div><p v-if="stepError.genderPolicy" class="field-error">{{ stepError.genderPolicy }}</p></fieldset>
          <label>Full address <span>*</span><q-input v-model="form.address" outlined type="textarea" rows="2" placeholder="Building, street, barangay, city" :error="!!stepError.address" :error-message="stepError.address" /></label>
          <label>Number of floors <span class="optional">Optional</span><q-input v-model.number="form.totalFloors" outlined type="number" min="1" inputmode="numeric" placeholder="e.g. 3" /></label>
          <label>Short description <span>*</span><q-input v-model="form.description" outlined type="textarea" rows="4" placeholder="Describe the accommodation, location, and what residents should know." :error="!!stepError.description" :error-message="stepError.description" /></label>
        </div>

        <div v-else-if="currentStep === 2" class="step-content">
          <div class="step-copy"><h2>Exterior and arrival</h2><p>Add real photos of the exterior, entrance, signage, or parking so students can recognize the accommodation.</p></div>
          <PhotoPicker label="Add exterior photos" hint="Optional. The first image will be the accommodation cover." :photos="form.exteriorImages" show-cover @select="onPhotosSelected($event, form.exteriorImages)" @remove="removePhoto(form.exteriorImages, $event)" />
        </div>

        <div v-else-if="currentStep === 3" class="step-content">
          <div class="step-copy"><h2>Shared spaces</h2><p>Add only areas shared by residents, such as a common kitchen or shared bathroom.</p></div>
          <article v-for="(facility, index) in form.sharedFacilities" :key="facility.id" class="facility-card">
            <div class="card-heading"><strong>Shared facility {{ index + 1 }}</strong><button type="button" class="text-danger" :aria-label="`Remove shared facility ${index + 1}`" @click="removeFacility(form.sharedFacilities, index)"><IconifyIcon icon="lucide:trash-2" width="17" aria-hidden="true" /> Remove</button></div>
            <label>Facility type <span>*</span><q-select v-model="facility.type" :options="facilityTypes" outlined dense emit-value map-options /></label>
            <label>Label <span class="optional">Optional</span><q-input v-model="facility.label" outlined dense :placeholder="facility.type === 'other' ? 'Required for other facility types' : 'e.g. Ground-floor shared kitchen'" /></label>
            <label>Description <span class="optional">Optional</span><q-input v-model="facility.description" outlined dense type="textarea" rows="2" placeholder="What should residents know?" /></label>
            <PhotoPicker label="Add facility photos" hint="Optional. Upload photos that show this specific space." :photos="facility.images" @select="onPhotosSelected($event, facility.images)" @remove="removePhoto(facility.images, $event)" />
          </article>
          <button type="button" class="add-outline" @click="addSharedFacility"><IconifyIcon icon="lucide:plus" width="18" aria-hidden="true" /> Add shared facility</button>
          <p v-if="stepError.facilities" class="field-error">{{ stepError.facilities }}</p>
        </div>

        <div v-else-if="currentStep === 4" class="step-content">
          <div class="step-copy"><h2>Rooms</h2><p>Each rentable room has its own type, rent, capacity, photos, and private facilities.</p></div>
          <article v-for="(room, index) in form.rooms" :key="room.id" class="room-card">
            <div class="card-heading"><div><strong>{{ room.label || `Room ${index + 1}` }}</strong><small>{{ roomSummary(room) }}</small></div><button type="button" class="text-danger" :aria-label="`Remove room ${index + 1}`" @click="removeRoom(index)"><IconifyIcon icon="lucide:trash-2" width="17" aria-hidden="true" /> Remove</button></div>
            <label>Room name or number <span>*</span><q-input v-model="room.label" outlined dense placeholder="e.g. Room 201" /></label>
            <label>Room type <span>*</span><q-select v-model="room.roomType" :options="roomTypes" outlined dense emit-value map-options /></label>
            <label v-if="room.roomType === 'custom'">Describe the room type <span>*</span><q-input v-model="room.customRoomType" outlined dense placeholder="e.g. Loft room" /></label>
            <div class="form-grid"><label>Capacity <span>*</span><q-input v-model.number="room.capacity" outlined dense type="number" min="1" inputmode="numeric" /></label><label>Monthly rent <span>*</span><q-input v-model.number="room.monthlyRent" outlined dense type="number" min="0" inputmode="decimal" prefix="₱" /></label></div>
            <div class="form-grid"><label>Floor <span class="optional">Optional</span><q-input v-model.number="room.floor" outlined dense type="number" min="1" inputmode="numeric" /></label><label>Status <span>*</span><q-select v-model="room.status" :options="roomStatuses" outlined dense emit-value map-options /></label></div>
            <PhotoPicker label="Add room photos" hint="Optional. Show the room interior and sleeping area." :photos="room.images" @select="onPhotosSelected($event, room.images)" @remove="removePhoto(room.images, $event)" />
            <div class="subsection"><div class="subsection-heading"><div><strong>Private facilities</strong><span>Only areas exclusive to this room.</span></div><button type="button" class="small-add" @click="addPrivateFacility(room)"><IconifyIcon icon="lucide:plus" width="16" aria-hidden="true" /> Add</button></div><article v-for="(facility, facilityIndex) in room.privateFacilities" :key="facility.id" class="private-facility"><div class="card-heading"><strong>Private facility {{ facilityIndex + 1 }}</strong><button type="button" class="text-danger" :aria-label="`Remove private facility ${facilityIndex + 1}`" @click="removeFacility(room.privateFacilities, facilityIndex)"><IconifyIcon icon="lucide:trash-2" width="16" aria-hidden="true" /> Remove</button></div><label>Facility type <span>*</span><q-select v-model="facility.type" :options="facilityTypes" outlined dense emit-value map-options /></label><label>Label <span class="optional">Optional</span><q-input v-model="facility.label" outlined dense :placeholder="facility.type === 'other' ? 'Required for other facility types' : 'e.g. Private kitchenette'" /></label><PhotoPicker label="Add facility photos" hint="Optional. Keep these photos specific to this room." :photos="facility.images" @select="onPhotosSelected($event, facility.images)" @remove="removePhoto(facility.images, $event)" /></article></div>
          </article>
          <button type="button" class="add-outline" @click="addRoom"><IconifyIcon icon="lucide:plus" width="18" aria-hidden="true" /> Add room</button>
          <p v-if="stepError.rooms" class="field-error">{{ stepError.rooms }}</p>
        </div>

        <div v-else class="step-content">
          <div class="step-copy"><h2>Rules and review</h2><p>Finish general accommodation details, then review the setup before saving.</p></div>
          <fieldset><legend>Included amenities <span class="optional">Optional</span></legend><div class="amenity-grid"><button v-for="amenity in amenitiesOptions" :key="amenity.value" type="button" :class="{ active: form.amenities.includes(amenity.value) }" :aria-pressed="form.amenities.includes(amenity.value)" @click="toggleAmenity(amenity.value)"><IconifyIcon :icon="amenity.icon" width="19" aria-hidden="true" /> {{ amenity.label }}</button></div></fieldset>
          <fieldset><legend>House rules <span class="optional">Optional</span></legend><div v-if="form.rules.length" class="rules-list"><div v-for="(rule, index) in form.rules" :key="`${rule}-${index}`"><span>{{ rule }}</span><button type="button" :aria-label="`Remove rule: ${rule}`" @click="removeRule(index)"><IconifyIcon icon="lucide:x" width="16" aria-hidden="true" /></button></div></div><div class="rule-entry"><q-input v-model="newRule" outlined dense placeholder="e.g. No smoking indoors" @keyup.enter="addRule" /><button type="button" @click="addRule">Add rule</button></div></fieldset>
          <section class="review-card" aria-labelledby="review-heading"><h3 id="review-heading">Setup review</h3><div><span>Accommodation type</span><strong>{{ accommodationTypeLabel }}</strong></div><div><span>Exterior photos</span><strong>{{ form.exteriorImages.length }}</strong></div><div><span>Shared facilities</span><strong>{{ form.sharedFacilities.length }}</strong></div><div><span>Rooms</span><strong>{{ form.rooms.length }}</strong></div><div><span>Total capacity</span><strong>{{ totalCapacity }} spaces</strong></div><p v-if="!form.exteriorImages.length">No exterior photos have been added.</p><p v-if="form.rooms.some((room) => !room.images.length)">One or more rooms have no interior photos.</p></section>
        </div>
      </section>

      <footer class="setup-footer"><button type="button" class="back-button" :disabled="currentStep === 1 || saving" @click="currentStep -= 1">Back</button><button v-if="currentStep < steps.length" type="button" class="next-button" @click="goNext">Continue <IconifyIcon icon="lucide:arrow-right" width="17" aria-hidden="true" /></button><button v-else type="button" class="next-button" :disabled="saving" @click="saveAccommodation"><IconifyIcon icon="lucide:check" width="17" aria-hidden="true" /> {{ saving ? 'Saving setup' : 'Create accommodation' }}</button></footer>
    </main>
  </q-page>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { Icon as IconifyIcon } from '@iconify/vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import { useLandlordStore } from '@/stores/landlord'
import PhotoPicker from '@/modules/landlord/components/AccommodationPhotoPicker.vue'

type RoomStatus = 'available' | 'occupied' | 'maintenance'
interface Photo { file: File; preview: string }
interface Facility { id: string; type: string; label: string; description: string; images: Photo[] }
interface Room { id: string; label: string; roomType: string; customRoomType: string; floor: number | null; capacity: number | null; monthlyRent: number | null; status: RoomStatus; images: Photo[]; privateFacilities: Facility[] }
const router = useRouter(); const $q = useQuasar(); const landlordStore = useLandlordStore(); const currentStep = ref(1); const saving = ref(false); const newRule = ref(''); const stepError = ref<Record<string, string>>({})
const steps = [{ value: 1, label: 'About' }, { value: 2, label: 'Exterior' }, { value: 3, label: 'Shared' }, { value: 4, label: 'Rooms' }, { value: 5, label: 'Review' }]
const accommodationTypes = [{ label: 'Boarding house', value: 'boarding_house' }, { label: 'Dormitory / residence hall', value: 'residence_hall' }, { label: 'Apartment building', value: 'apartment_building' }, { label: 'Apartment unit', value: 'apartment_unit' }, { label: 'House', value: 'house' }, { label: 'Condominium unit', value: 'condominium_unit' }, { label: 'Bedspace facility', value: 'bedspace_facility' }, { label: 'Other', value: 'other' }]
const genderOptions = [{ label: 'Boys only', value: 'boys' }, { label: 'Girls only', value: 'girls' }, { label: 'Co-ed', value: 'coed' }]; const roomTypes = [{ label: 'Solo room', value: 'solo' }, { label: 'Duo room', value: 'duo' }, { label: 'Triple room', value: 'triple' }, { label: 'Bedspace', value: 'bedspace' }, { label: 'Studio', value: 'studio' }, { label: 'Other', value: 'custom' }]; const roomStatuses = [{ label: 'Available', value: 'available' }, { label: 'Occupied', value: 'occupied' }, { label: 'Maintenance', value: 'maintenance' }]; const facilityTypes = [{ label: 'Bathroom / CR', value: 'bathroom' }, { label: 'Kitchen / kitchenette', value: 'kitchen' }, { label: 'Laundry area', value: 'laundry' }, { label: 'Balcony', value: 'balcony' }, { label: 'Common area', value: 'common_area' }, { label: 'Study area', value: 'study_area' }, { label: 'Parking', value: 'parking' }, { label: 'Other', value: 'other' }]; const amenitiesOptions = [{ label: 'Wi-Fi', value: 'wifi', icon: 'lucide:wifi' }, { label: 'Water', value: 'water', icon: 'lucide:droplets' }, { label: 'Electricity', value: 'electric', icon: 'lucide:zap' }, { label: 'Air conditioning', value: 'aircon', icon: 'lucide:wind' }]
const form = ref({ name: '', accommodationType: '', customAccommodationType: '', genderPolicy: '', address: '', totalFloors: null as number | null, description: '', exteriorImages: [] as Photo[], sharedFacilities: [] as Facility[], rooms: [] as Room[], amenities: [] as string[], rules: [] as string[] })
const stepTitle = computed(() => steps.find((step) => step.value === currentStep.value)?.label || 'Setup'); const accommodationTypeLabel = computed(() => form.value.accommodationType === 'other' ? form.value.customAccommodationType || 'Other' : accommodationTypes.find((item) => item.value === form.value.accommodationType)?.label || 'Not set'); const totalCapacity = computed(() => form.value.rooms.reduce((total, room) => total + Math.max(Number(room.capacity) || 0, 0), 0))
function createId() { return globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}` }; function newFacility(): Facility { return { id: createId(), type: '', label: '', description: '', images: [] } }; function addSharedFacility() { form.value.sharedFacilities.push(newFacility()) }; function addPrivateFacility(room: Room) { room.privateFacilities.push(newFacility()) }; function addRoom() { form.value.rooms.push({ id: createId(), label: '', roomType: '', customRoomType: '', floor: null, capacity: null, monthlyRent: null, status: 'available', images: [], privateFacilities: [] }) }; function removeRoom(index: number) { form.value.rooms.splice(index, 1) }; function removeFacility(facilities: Facility[], index: number) { facilities.splice(index, 1) }
function onPhotosSelected(event: Event, target: Photo[]) { const input = event.target as HTMLInputElement; for (const file of Array.from(input.files || [])) { if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { $q.notify({ type: 'negative', message: 'Use JPG, PNG, or WebP images only.', position: 'top' }); continue }; if (file.size > 5 * 1024 * 1024) { $q.notify({ type: 'negative', message: 'Each photo must be 5 MB or smaller.', position: 'top' }); continue }; target.push({ file, preview: URL.createObjectURL(file) }) }; input.value = '' }; function removePhoto(target: Photo[], index: number) { const [photo] = target.splice(index, 1); if (photo) URL.revokeObjectURL(photo.preview) }
function toggleAmenity(amenity: string) { const index = form.value.amenities.indexOf(amenity); if (index === -1) form.value.amenities.push(amenity); else form.value.amenities.splice(index, 1) }; function addRule() { const rule = newRule.value.trim(); if (rule && !form.value.rules.includes(rule)) form.value.rules.push(rule); newRule.value = '' }; function removeRule(index: number) { form.value.rules.splice(index, 1) }; function roomSummary(room: Room) { const type = room.roomType === 'custom' ? room.customRoomType : roomTypes.find((item) => item.value === room.roomType)?.label; const capacity = room.capacity ? `${room.capacity} ${room.capacity === 1 ? 'space' : 'spaces'}` : 'capacity not set'; return [type || 'type not set', capacity].join(' · ') }
function validateStep(step: number) { const errors: Record<string, string> = {}; if (step === 1) { if (!form.value.name.trim()) errors.name = 'Enter the accommodation name.'; if (!form.value.accommodationType) errors.accommodationType = 'Choose an accommodation type.'; if (form.value.accommodationType === 'other' && !form.value.customAccommodationType.trim()) errors.accommodationType = 'Describe the accommodation type.'; if (!form.value.genderPolicy) errors.genderPolicy = 'Choose who can stay.'; if (!form.value.address.trim()) errors.address = 'Enter the full address.'; if (!form.value.description.trim()) errors.description = 'Add a short description.' } if (step === 3 && form.value.sharedFacilities.some((facility) => !facility.type || (facility.type === 'other' && !facility.label.trim()))) errors.facilities = 'Choose a type for each shared facility. Other facilities need a label.'; if (step === 4) { if (!form.value.rooms.length) errors.rooms = 'Add at least one room.'; else if (form.value.rooms.some((room) => !room.label.trim() || !room.roomType || (room.roomType === 'custom' && !room.customRoomType.trim()) || !room.capacity || room.capacity < 1 || room.monthlyRent === null || room.monthlyRent < 0 || room.privateFacilities.some((facility) => !facility.type || (facility.type === 'other' && !facility.label.trim())))) errors.rooms = 'Complete every room’s name, type, capacity, rent, and private facilities.' }; stepError.value = errors; return !Object.keys(errors).length }
function goNext() { if (validateStep(currentStep.value)) currentStep.value += 1 }; function goToStep(step: number) { if (step <= currentStep.value) currentStep.value = step }; function handleClose() { void router.push('/landlord/properties') }
async function saveAccommodation() { if (!validateStep(4)) { currentStep.value = 4; return }; saving.value = true; try { const success = await landlordStore.addProperty({ name: form.value.name.trim(), accommodationType: form.value.accommodationType === 'other' ? form.value.customAccommodationType.trim() : form.value.accommodationType, address: form.value.address.trim(), description: form.value.description.trim(), totalFloors: form.value.totalFloors, genderPolicy: form.value.genderPolicy, amenities: form.value.amenities, rules: form.value.rules, exteriorImages: form.value.exteriorImages.map((photo) => photo.file), sharedFacilities: form.value.sharedFacilities.map((facility) => ({ ...facility, images: facility.images.map((photo) => photo.file) })), rooms: form.value.rooms.map((room) => ({ ...room, images: room.images.map((photo) => photo.file), privateFacilities: room.privateFacilities.map((facility) => ({ ...facility, images: facility.images.map((photo) => photo.file) })) })) }); if (!success) throw new Error('Unable to create the accommodation.'); $q.notify({ type: 'positive', message: 'Accommodation created. You can continue managing rooms and details.', position: 'top' }); void router.push('/landlord/properties') } catch (error) { $q.notify({ type: 'negative', message: error instanceof Error ? error.message : 'Unable to create the accommodation.', position: 'top' }) } finally { saving.value = false } }
</script>

<style scoped>
.setup-page { min-height: 100%; background: var(--m-bg); color: var(--m-text); }.setup-shell { width: 100%; max-width: 680px; margin: 0 auto; padding: max(12px, env(safe-area-inset-top)) var(--m-page-gutter) max(100px, calc(24px + env(safe-area-inset-bottom))); }.setup-header { display: grid; grid-template-columns: 44px 1fr; align-items: center; gap: 10px; margin-bottom: 18px; }.close-button { display: grid; width: 44px; height: 44px; place-items: center; border: 1px solid var(--m-border); border-radius: 8px; background: var(--m-surface); color: var(--m-primary-dark); }.setup-header h1 { margin: 0; color: var(--m-ink); font-size: 18px; font-weight: 800; }.setup-header p { margin: 3px 0 0; color: var(--m-muted); font-size: 12px; font-weight: 650; }.stepper { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); margin: 0 -12px 20px; padding: 0 12px 10px; overflow-x: auto; border-bottom: 1px solid var(--m-border); background: var(--m-surface); }.stepper button { display: grid; min-width: 55px; justify-items: center; gap: 5px; padding: 4px; border: 0; background: transparent; color: var(--m-muted); font-size: 10px; font-weight: 750; }.stepper span { display: grid; width: 26px; height: 26px; place-items: center; border: 1px solid var(--m-border); border-radius: 50%; background: var(--m-surface); }.stepper button.active,.stepper button.complete { color: var(--m-primary-dark); }.stepper button.active span,.stepper button.complete span { border-color: var(--m-primary); background: var(--m-primary); color: #fff; }.step-content { display: grid; gap: 16px; }.step-copy h2 { margin: 0; color: var(--m-ink); font-size: 20px; font-weight: 800; }.step-copy p { margin: 5px 0 0; color: var(--m-muted); font-size: 13px; line-height: 1.45; }.step-content > label,.facility-card label,.room-card > label,.private-facility label { display: grid; gap: 6px; color: var(--m-text); font-size: 12px; font-weight: 750; }.step-content label > span,.step-content legend > span { color: var(